    def search_tasks(self, query: str, field: str = "description") -> dict[str, Any]:
        """Search tasks by description, project, tags, or UDA values."""
        params = {"query": query, "field": field}
        try:
            self._guard_rate()
            sanitized_query = sanitize_filter_expression(query)
            if field == "description":
                filter_expr = f"description.contains:{sanitized_query}"
            elif field == "project":
                filter_expr = f"project:{sanitized_query}"
            elif field == "tags":
                filter_expr = f"+{sanitize_tag(sanitized_query)}"
            else:
                filter_expr = f"{field}:{sanitized_query}"
            tasks, ms = _timed_call(self.task.export_tasks, filter_expr)
            tasks = _redact_list(tasks, self.config.redacted_fields)
            self._log("search_tasks", params, f"{len(tasks)} results", True, ms)
            return _make_success(
                f"Found {len(tasks)} matching tasks.",
                tasks=tasks,
                count=len(tasks),
            )
        except (RateLimitError, SanitizationError) as e:
            self._log(
                "search_tasks",
                params,
                "",
                False,
                0,
                str(e),
                result_code=_result_code_from_exception(e),
            )
            return _error_from_known_exception(e)
        except Exception as e:
            self._log("search_tasks", params, "", False, 0, str(e), result_code="internal_error")
            return _make_coded_error(f"Search failed: {e}", "internal_error")

