    def create_task(
        self,
        description: str,
        project: str = "",
        priority: str = "",
        tags: list[str] | None = None,
        due: str = "",
        dry_run: bool | None = None,
        **udas: str,
    ) -> dict[str, Any]:
        """Create a new task with schema validation."""
        params = {
            "description": description,
            "project": project,
            "priority": priority,
            "tags": tags,
            "dry_run": dry_run,
            **udas,
        }
        try:
            self._guard_rate(is_create=True)

            clean_desc = sanitize_description(description)
            task_data: dict[str, Any] = {"description": clean_desc}

            if project:
                task_data["project"] = sanitize_project(project)
            if priority:
                task_data["priority"] = sanitize_enum(priority, "priority", ["H", "M", "L"])
            if due:
                task_data["due"] = sanitize_field_value(due, "due")

            clean_tags: list[str] = []
            if tags:
                clean_tags = [sanitize_tag(t) for t in tags]
                task_data["tags"] = clean_tags

            for key, value in udas.items():
                if value:
                    if key in self.schema.enum_fields():
                        task_data[key] = sanitize_enum(value, key, self.schema.enum_fields()[key])
                    else:
                        task_data[key] = sanitize_field_value(value, key)

            validation_errors = validate_task(task_data, self.schema)
            if validation_errors:
                self._log(
                    "create_task",
                    params,
                    "validation failed",
                    False,
                    0,
                    "; ".join(validation_errors),
                    result_code="validation_error",
                )
                return _make_coded_error(
                    f"Schema validation failed: {'; '.join(validation_errors)}",
                    "validation_error",
                )

            cli_fields: dict[str, str] = {}
            for key, value in task_data.items():
                if key in ("description", "tags"):
                    continue
                cli_fields[key] = value
            if clean_tags:
                cli_fields["tags"] = clean_tags

            if self._effective_dry_run(dry_run):
                self._log("create_task", params, "dry_run", True, 0, result_code="dry_run")
                return _make_success(
                    f"DRY RUN: Would create task '{clean_desc}'.",
                    code="dry_run",
                    dry_run=True,
                    preview={"description": clean_desc, "fields": cli_fields},
                )

            result, ms = _timed_call(self.task.add_task, clean_desc, **cli_fields)
            if result.ok:
                self._log("create_task", params, result.stdout, True, ms)
                return _make_success(f"Task created. {result.stdout.strip()}")
            self._log("create_task", params, result.stderr, False, ms, result.stderr)
            return _make_coded_error(f"Create failed: {result.stderr}", "cli_error")
        except (RateLimitError, SanitizationError) as e:
            self._log("create_task", params, "", False, 0, str(e))
            return _error_from_known_exception(e)
        except Exception as e:
            self._log("create_task", params, "", False, 0, str(e))
            return _make_coded_error(f"Create failed: {e}", "internal_error")

    def create_subtask(
        self,
        parent_uuid: str,
        description: str,
        project: str = "",
        priority: str = "",
        tags: list[str] | None = None,
        due: str = "",
        dry_run: bool | None = None,
        **udas: str,
    ) -> dict[str, Any]:
        """Create a subtask with depends: linking to a parent task."""
        params = {
            "parent_uuid": parent_uuid,
            "description": description,
            "project": project,
            "priority": priority,
            "tags": tags,
            "dry_run": dry_run,
            **udas,
        }
        try:
            self._guard_rate(is_create=True)

            clean_parent_uuid = sanitize_uuid(parent_uuid)
            parent_task = self.task.get_task(clean_parent_uuid)
            if not parent_task:
                self._log(
                    "create_subtask",
                    params,
                    "parent not found",
                    False,
                    0,
                    f"Parent task {clean_parent_uuid} not found",
                    result_code="not_found",
                )
                return _make_coded_error(
                    f"Parent task {clean_parent_uuid} not found.",
                    "not_found",
                )

            clean_desc = sanitize_description(description)
            task_data: dict[str, Any] = {
                "description": clean_desc,
                "depends": clean_parent_uuid,
            }

            if project:
                task_data["project"] = sanitize_project(project)
            if priority:
                task_data["priority"] = sanitize_enum(priority, "priority", ["H", "M", "L"])
            if due:
                task_data["due"] = sanitize_field_value(due, "due")

            clean_tags: list[str] = []
            if tags:
                clean_tags = [sanitize_tag(t) for t in tags]
                task_data["tags"] = clean_tags

            for key, value in udas.items():
                if value:
                    if key in self.schema.enum_fields():
                        task_data[key] = sanitize_enum(value, key, self.schema.enum_fields()[key])
                    else:
                        task_data[key] = sanitize_field_value(value, key)

            validation_errors = validate_task(task_data, self.schema)
            if validation_errors:
                self._log(
                    "create_subtask",
                    params,
                    "validation failed",
                    False,
                    0,
                    "; ".join(validation_errors),
                    result_code="validation_error",
                )
                return _make_coded_error(
                    f"Schema validation failed: {'; '.join(validation_errors)}",
                    "validation_error",
                )

            cli_fields: dict[str, str] = {}
            for key, value in task_data.items():
                if key in ("description", "tags"):
                    continue
                cli_fields[key] = value
            if clean_tags:
                cli_fields["tags"] = clean_tags

            if self._effective_dry_run(dry_run):
                self._log("create_subtask", params, "dry_run", True, 0, result_code="dry_run")
                return _make_success(
                    f"DRY RUN: Would create subtask under {clean_parent_uuid}.",
                    code="dry_run",
                    dry_run=True,
                    preview={"description": clean_desc, "fields": cli_fields},
                )

            result, ms = _timed_call(self.task.add_task, clean_desc, **cli_fields)
            if result.ok:
                self._log("create_subtask", params, result.stdout, True, ms)
                return _make_success(
                    f"Subtask created with parent {clean_parent_uuid}. {result.stdout.strip()}"
                )
            self._log("create_subtask", params, result.stderr, False, ms, result.stderr)
            return _make_coded_error(f"Create subtask failed: {result.stderr}", "cli_error")
        except (RateLimitError, SanitizationError) as e:
            self._log("create_subtask", params, "", False, 0, str(e))
            return _error_from_known_exception(e)
        except Exception as e:
            self._log("create_subtask", params, "", False, 0, str(e))
            return _make_coded_error(f"Create subtask failed: {e}", "internal_error")

    def batch_create_tasks(
        self,
        tasks: list[dict[str, Any]],
        dry_run: bool | None = None,
    ) -> dict[str, Any]:
        """Create multiple tasks with partial-result reporting."""
        params = {"task_count": len(tasks), "dry_run": dry_run}
        if not tasks:
            return _make_coded_error("No tasks provided for batch creation.", "validation_error")

        results: list[dict[str, Any]] = []
        created_count = 0
        failed_count = 0

        for idx, item in enumerate(tasks):
            if not isinstance(item, dict):
                failed_count += 1
                results.append(
                    {
                        "index": idx,
                        "result": _make_coded_error(
                            "Each batch entry must be an object.",
                            "validation_error",
                        ),
                    }
                )
                continue

            raw_tags = item.get("tags")
            if isinstance(raw_tags, str):
                tag_list: list[str] | None = [t.strip() for t in raw_tags.split(",") if t.strip()]
            elif isinstance(raw_tags, list):
                tag_list = raw_tags
            else:
                tag_list = None

            raw_extra = item.get("extra_fields")
            extra_fields: dict[str, Any] = raw_extra if isinstance(raw_extra, dict) else {}

            task_result = self.create_task(
                description=str(item.get("description", "")),
                project=str(item.get("project", "")),
                priority=str(item.get("priority", "")),
                tags=tag_list,
                due=str(item.get("due", "")),
                dry_run=dry_run,
                **extra_fields,
            )

            results.append({"index": idx, "result": task_result})
            if task_result.get("success"):
                created_count += 1
                continue

            failed_count += 1
            if task_result.get("code") == "rate_limit":
                self._log(
                    "batch_create_tasks",
                    params,
                    "rate limit",
                    False,
                    0,
                    result_code="rate_limit",
                )
                return _make_coded_error(
                    "Batch creation stopped by rate limit.",
                    "rate_limit",
                    details={
                        "created_count": created_count,
                        "failed_count": failed_count,
                        "total": len(tasks),
                        "failed_index": idx,
                        "results": results,
                        **dict(task_result.get("details") or {}),
                    },
                )

        self._log(
            "batch_create_tasks",
            params,
            f"created={created_count} failed={failed_count}",
            True,
            0,
            result_code="ok" if failed_count == 0 else "validation_error",
        )
        if failed_count == 0:
            return _make_success(
                f"Batch create succeeded for {created_count} tasks.",
                created_count=created_count,
                failed_count=0,
                results=results,
            )
        return _make_coded_error(
            f"Batch create completed with {failed_count} failures.",
            "validation_error",
            details={
                "created_count": created_count,
                "failed_count": failed_count,
                "total": len(tasks),
                "results": results,
            },
        )

