    # MANAGER tools
    # -----------------------------------------------------------------------

    def bulk_modify(
        self,
        filters: str,
        fields: dict[str, str | list[str]],
        dry_run: bool | None = None,
        confirm_token: str = "",
    ) -> dict[str, Any]:
        """Modify all tasks matching a filter expression."""
        params = {
            "filters": filters,
            "fields": fields,
            "dry_run": dry_run,
            "confirm_token": bool(confirm_token),
        }
        try:
            self._guard_rate()
            clean_filters = sanitize_filter_expression(filters)
            filter_parts = clean_filters.split() if clean_filters else []
            tasks, ms = _timed_call(self.task.export_tasks, *filter_parts)
            if not tasks:
                self._log("bulk_modify", params, "no tasks", False, ms, result_code="not_found")
                return _make_coded_error(
                    f"No tasks matched filter '{clean_filters}'.",
                    "not_found",
                )

            task_count = len(tasks)
            task_uuids = [str(task.get("uuid", "")) for task in tasks if task.get("uuid")]
            if self._effective_dry_run(dry_run):
                self._log("bulk_modify", params, "dry_run", True, ms, result_code="dry_run")
                return _make_success(
                    f"DRY RUN: Would modify {task_count} tasks.",
                    code="dry_run",
                    dry_run=True,
                    preview={"task_count": task_count, "task_uuids": task_uuids, "fields": fields},
                )

            if self.config.require_confirmation:
                token_subject = f"{clean_filters}:{task_count}"
                required_token = self._confirmation_token("bulk_modify", token_subject)
                if confirm_token != required_token:
                    self._log(
                        "bulk_modify",
                        params,
                        "confirmation_required",
                        True,
                        ms,
                        result_code="confirmation_required",
                    )
                    return _make_success(
                        (
                            f"CONFIRMATION REQUIRED: Modify {task_count} tasks "
                            f"matching '{clean_filters}'. Re-call bulk_modify "
                            "with confirm_token from details."
                        ),
                        code="confirmation_required",
                        needs_confirmation=True,
                        details={
                            "confirmation_token": required_token,
                            "task_count": task_count,
                        },
                    )

            modified_count = 0
            failed: list[dict[str, Any]] = []
            for uuid in task_uuids:
                modify_result = self.modify_task(uuid=uuid, fields=fields, dry_run=False)
                if modify_result.get("success"):
                    modified_count += 1
                    continue
                failed.append({"uuid": uuid, "result": modify_result})
                if modify_result.get("code") == "rate_limit":
                    self._log(
                        "bulk_modify",
                        params,
                        "rate limit",
                        False,
                        0,
                        result_code="rate_limit",
                    )
                    return _make_coded_error(
                        "Bulk modify stopped by rate limit.",
                        "rate_limit",
                        details={
                            "modified_count": modified_count,
                            "failed_count": len(failed),
                            "task_count": task_count,
                            "failed": failed,
                            **dict(modify_result.get("details") or {}),
                        },
                    )

            if failed:
                self._log(
                    "bulk_modify",
                    params,
                    f"partial success modified={modified_count} failed={len(failed)}",
                    False,
                    0,
                    result_code="validation_error",
                )
                return _make_coded_error(
                    f"Bulk modify completed with {len(failed)} failures.",
                    "validation_error",
                    details={
                        "modified_count": modified_count,
                        "failed_count": len(failed),
                        "task_count": task_count,
                        "failed": failed,
                    },
                )

            self._log(
                "bulk_modify",
                params,
                f"modified={modified_count}",
                True,
                0,
            )
            return _make_success(
                f"Modified {modified_count} tasks.",
                modified_count=modified_count,
                task_count=task_count,
            )
        except (RateLimitError, SanitizationError) as e:
            self._log(
                "bulk_modify",
                params,
                "",
                False,
                0,
                str(e),
                result_code=_result_code_from_exception(e),
            )
            return _error_from_known_exception(e)
        except Exception as e:
            self._log(
                "bulk_modify",
                params,
                "",
                False,
                0,
                str(e),
                result_code="internal_error",
            )
            return _make_coded_error(f"Bulk modify failed: {e}", "internal_error")

    def complete_task(
        self,
        uuid: str,
        dry_run: bool | None = None,
        confirm_token: str = "",
    ) -> dict[str, Any]:
        """Mark a task as done."""
        params = {"uuid": uuid, "dry_run": dry_run, "confirm_token": bool(confirm_token)}
        effective_dry = self._effective_dry_run(dry_run)
        try:
            self._guard_rate()
            clean_uuid = sanitize_uuid(uuid)

            if effective_dry:
                task_data = self.task.get_task(clean_uuid)
                if not task_data:
                    return _make_coded_error(f"Task {clean_uuid} not found.", "not_found")
                self._log("complete_task", params, "dry_run", True, 0, result_code="dry_run")
                return _make_success(
                    f"DRY RUN: Would complete task '{task_data.get('description', '')}'.",
                    code="dry_run",
                    dry_run=True,
                    task=_redact_fields(task_data, self.config.redacted_fields),
                )

            if self.config.require_confirmation:
                task_data = self.task.get_task(clean_uuid)
                if not task_data:
                    return _make_coded_error(f"Task {clean_uuid} not found.", "not_found")
                required_token = self._confirmation_token("complete_task", clean_uuid)
                if confirm_token != required_token:
                    self._log(
                        "complete_task",
                        params,
                        "confirmation_required",
                        True,
                        0,
                        result_code="confirmation_required",
                    )
                    return _make_success(
                        "CONFIRMATION REQUIRED: Complete task "
                        f"'{task_data.get('description', '')}'. "
                        "Re-call complete_task with confirm_token from details.",
                        code="confirmation_required",
                        details={"confirmation_token": required_token},
                        needs_confirmation=True,
                        task=_redact_fields(task_data, self.config.redacted_fields),
                    )

            result, ms = _timed_call(self.task.done_task, clean_uuid)
            if result.ok:
                self._log("complete_task", params, "ok", True, ms)
                return _make_success(f"Task {clean_uuid} completed.")
            self._log("complete_task", params, result.stderr, False, ms, result.stderr)
            return _make_coded_error(f"Complete failed: {result.stderr}", "cli_error")
        except (RateLimitError, SanitizationError) as e:
            self._log("complete_task", params, "", False, 0, str(e))
            return _error_from_known_exception(e)
        except Exception as e:
            self._log("complete_task", params, "", False, 0, str(e))
            return _make_coded_error(f"Complete failed: {e}", "internal_error")

